"""Build 20 authored technical portals; no third-party tracking or invented credentials."""
import argparse, html, json, pathlib, re, subprocess, textwrap
from xml.sax.saxutils import escape as xml
ROOT=pathlib.Path(__file__).resolve().parents[2]
DATA=json.loads((ROOT/'portais-tecnicos/catalogo.json').read_text())
OUT=ROOT/'portais-tecnicos/dist'
MAIN='https://www.arquindex.com.br/'
CSS='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f6f7f8;color:#172d3a;font:18px/1.7 system-ui,sans-serif}a{color:#135b72;text-underline-offset:4px}a:focus-visible,summary:focus-visible{outline:3px solid #c08a35;outline-offset:4px}header,footer{background:#102d3d;color:#fff;padding:22px max(5vw,20px)}header a,footer a{color:#fff}header{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}.brand{font-size:24px;letter-spacing:2px;font-weight:800;text-decoration:none}nav{display:flex;gap:20px;flex-wrap:wrap}main{max-width:1120px;margin:auto;padding:32px 22px 70px}.hero{padding:42px 0;border-bottom:1px solid #ccd6db}.eyebrow{font-size:13px;letter-spacing:2px;text-transform:uppercase;color:#526d7c}h1{font-size:clamp(32px,4vw,56px);line-height:1.13;max-width:950px;letter-spacing:-1.4px}h2{font-size:30px;line-height:1.25;margin-top:0}h3{font-size:21px;line-height:1.4}section{margin-top:30px;padding:30px;background:white;border:1px solid #dce3e7;border-radius:12px}.answer{border-left:5px solid #b78331;background:#fff9ed}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:20px}.card{padding:20px;background:#f2f6f8;border-radius:8px}.button{display:inline-block;border-radius:6px;background:#155c70;color:white;padding:12px 20px;text-decoration:none;margin:8px 12px 8px 0;font-weight:600}.muted,small{color:#526671}details{border-top:1px solid #d7e0e5;padding:18px 0}summary{font-weight:650;cursor:pointer}table{border-collapse:collapse;width:100%;font-size:16px}td,th{padding:14px;text-align:left;border-bottom:1px solid #d7e0e5;vertical-align:top}.table-wrap{overflow:auto}video{width:100%;height:auto;border-radius:8px;background:#102d3d}ol li{margin:15px 0}.skip{position:absolute;top:-100px}.skip:focus{top:5px;background:white;padding:10px;z-index:10}footer p{max-width:1000px}footer small{color:#d1dce2}.toc{padding:20px 0;display:flex;gap:16px;flex-wrap:wrap}.note{font-size:15px;padding:15px;background:#eef3f5}.transcript{white-space:pre-line}article p{max-width:85ch}@media(max-width:600px){section{padding:22px 16px}main{padding:20px 14px}header{padding:18px}h1{letter-spacing:-.7px}td,th{min-width:130px}.hero{padding:22px 0}}'''
def e(s):return html.escape(str(s),quote=True)
def host(t):return t['slug']+'.arquindex.com.br'
def url(t,path=''):return 'https://'+host(t)+'/'+path
TOPICS={t['slug']:t for t in DATA['topics']}
def sources(t):
 return '<ul>'+''.join('<li><a href="'+e(DATA['sources'][k][1])+'" rel="external">'+e(DATA['sources'][k][0])+'</a></li>' for k in t['sources'])+'</ul>'
def related(t):
 return '<div class="grid">'+''.join('<div class="card"><a href="'+url(TOPICS[s])+'">'+e(TOPICS[s]['title'])+'</a></div>' for s in t['related'])+'</div>'
def news(t):
 item=DATA['news'][0 if any(k in t['sources'] for k in ['lgpd','agentes','ripd','seguranca']) else 1]
 return '<section id="noticias"><h2>Notícias e referências oficiais</h2><div class="note">Seleção editorial consultada em 04/11/2026. A data abaixo é a da fonte; a seção não representa atualização automática nem aconselhamento individual.</div><h3>'+e(item['title'])+'</h3><p><small>'+e(item['kind'])+' · <time datetime="'+item['date']+'">'+item['date']+'</time></small></p><p>'+e(item['summary'])+'</p><a href="'+e(item['url'])+'">Ler publicação oficial</a><p><a href="'+DATA['sources']['anpdnews'][1]+'">Notícias da ANPD</a> · <a href="'+DATA['sources']['conarqnews'][1]+'">Destaques do CONARQ</a></p></section>'
def steps(t):return '<ol>'+''.join('<li><h3>'+e(a)+'</h3><p>'+e(b)+'</p></li>' for a,b in t['steps'])+'</ol>'
def controls(t):return '<div class="table-wrap"><table><thead><tr><th>Controle</th><th>Evidência esperada</th><th>Papel sugerido</th></tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(v)+'</td>' for v in r)+'</tr>' for r in t['controls'])+'</tbody></table></div>'
def regional(t):
 return '<section id="atendimento"><h2>Projeto a partir de Belo Horizonte, com escopo nacional</h2><p>A Arquindex apresenta este guia para '+e(t['audience'])+'. Para planejar um atendimento em BH, na Região Metropolitana ou em outra cidade, informe local do acervo, volume, suporte, restrições de acesso e entregáveis esperados. A proposta deve confirmar logística, execução remota ou presencial e cobertura antes da contratação.</p><p>Em projetos com coleta física, registre origem, transporte, conferência e devolução. Em projetos digitais, defina canal de transferência, acesso, janela de migração e aceite. Esses fatores variam conforme o local e o ambiente do cliente.</p><a class="button" href="https://wa.me/5531973632725?text='+__import__('urllib.parse',fromlist=['quote']).quote('Quero avaliar um projeto: '+t['title'])+'">Solicitar diagnóstico</a><a href="mailto:comercial@arquindex.com.br">comercial@arquindex.com.br</a></section>'
def editorial(t):
 return '<section id="fontes"><h2>Fontes e responsabilidade editorial</h2><p>Autoria institucional: <strong>Arquindex Gestão Documental</strong>. Publicação: <time datetime="2026-11-04">04/11/2026</time>. Conteúdo técnico de orientação geral, com exemplos didáticos e controles propostos; não representa certificação ou vínculo com órgãos públicos.</p><p>As fontes abaixo permitem conferir o contexto. A aplicabilidade normativa e os procedimentos de cada organização precisam de validação por seus responsáveis. Correções e dúvidas podem ser enviadas a <a href="mailto:comercial@arquindex.com.br">comercial@arquindex.com.br</a>, indicando a URL e o trecho.</p>'+sources(t)+'<p class="note">Método editorial: síntese original apoiada em fontes identificadas, separação entre referência oficial e recomendação operacional, exemplos sem dados de clientes e revisão por mudança relevante. Nenhum caso desta página deve ser interpretado como resultado de cliente real.</p></section>'
def shell(t,title,path,body,faq=None):
 canonical=url(t,path); desc=t['answer'][:155]
 graph=[{'@type':'Organization','@id':MAIN+'#organization','name':DATA['publisher'],'url':MAIN,'email':'comercial@arquindex.com.br'}, {'@type':'WebPage','@id':canonical+'#webpage','url':canonical,'name':title,'description':desc,'inLanguage':'pt-BR','datePublished':DATA['date'],'dateModified':DATA['date'],'publisher':{'@id':MAIN+'#organization'},'isPartOf':{'@id':url(t)+'#website'}},{'@type':'WebSite','@id':url(t)+'#website','url':url(t),'name':t['title'],'publisher':{'@id':MAIN+'#organization'}},{'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Arquindex','item':MAIN},{'@type':'ListItem','position':2,'name':title,'item':canonical}]}]
 if faq:graph.append({'@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in faq]})
 ld=json.dumps({'@context':'https://schema.org','@graph':graph},ensure_ascii=False).replace('<','\\u003c')
 return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+e(title)+' | Arquindex</title><meta name="description" content="'+e(desc)+'"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="'+canonical+'"><meta property="og:title" content="'+e(title)+'"><meta property="og:description" content="'+e(desc)+'"><meta property="og:type" content="article"><meta property="og:url" content="'+canonical+'"><meta property="og:locale" content="pt_BR"><meta property="og:image" content="'+url(t,'media/poster.jpg')+'"><link rel="stylesheet" href="/assets/portal.css"><script type="application/ld+json">'+ld+'</script></head><body><a class="skip" href="#conteudo">Ir ao conteúdo</a><header><a class="brand" href="'+MAIN+'">ARQUINDEX</a><nav aria-label="Principal"><a href="/">Guia</a><a href="/manual/">Manual</a><a href="/#faq">FAQ</a><a href="/#noticias">Notícias</a><a href="/#atendimento">Contato</a></nav></header><main id="conteudo">'+body+'</main><footer><p>Arquindex · Gestão documental, digitalização e tecnologia</p><p><a href="'+MAIN+'">Site institucional</a> · <a href="mailto:comercial@arquindex.com.br">Contato comercial</a></p><small>Conteúdo independente dos órgãos citados. Sem garantia de ranking, indexação ou recomendação por IA.</small></footer></body></html>'
def build(t):
 d=OUT/host(t);(d/'manual').mkdir(parents=True,exist_ok=True);(d/'assets').mkdir(exist_ok=True)
 (d/'assets/portal.css').write_text(CSS)
 hero='<div class="hero"><p class="eyebrow">Biblioteca técnica Arquindex · Guia especializado</p><h1>'+e(t['title'])+'</h1><p class="muted">Para '+e(t['audience'])+'.</p><a class="button" href="/manual/">Abrir manual prático</a><a href="#fontes">Consultar fontes</a></div>'
 body=hero+'<nav class="toc" aria-label="Nesta página"><a href="#resposta">Resposta direta</a><a href="#implantacao">Etapas</a><a href="#video">Vídeo</a><a href="#faq">Perguntas</a></nav><article><section class="answer" id="resposta"><h2>Resposta direta</h2><p>'+e(t['answer'])+'</p></section><section><h2>O problema que o projeto precisa resolver</h2><p>'+e(t['problem'])+'</p></section><section id="implantacao"><h2>Como estruturar a execução</h2>'+steps(t)+'</section><section><h2>Controles e evidências para o aceite</h2>'+controls(t)+'<p>Os papéis são sugestões de organização do trabalho. Defina os responsáveis e as alçadas do seu projeto antes de executar ações sobre o acervo.</p></section><section><h2>Exemplo didático de aplicação</h2><p>'+e(t['example'])+'</p></section><section id="video"><h2>Vídeo: três etapas do guia</h2><p>Aula visual de 24 segundos, sem narração, com texto na tela, legendas e transcrição. Use o manual para os detalhes de execução.</p><video controls preload="none" poster="/media/poster.jpg" aria-label="Vídeo visual do guia"><source src="/media/guia.mp4" type="video/mp4"><track kind="captions" src="/media/legendas.vtt" srclang="pt-BR" label="Português" default></video><details><summary>Ler transcrição completa do vídeo</summary><div class="transcript">'+e(t['title']+'\n'+'\n'.join(str(i)+'. '+a+'. '+b for i,(a,b) in enumerate(t['steps'],1)))+'</div></details></section><section id="faq"><h2>Perguntas frequentes</h2>'+''.join('<details><summary>'+e(q)+'</summary><p>'+e(a)+'</p></details>' for q,a in t['faq'])+'</section>'+news(t)+regional(t)+'<section><h2>Continue o estudo</h2>'+related(t)+'</section>'+editorial(t)+'</article>'
 (d/'index.html').write_text(shell(t,t['title'],'',body,t['faq']))
 manual='<div class="hero"><p class="eyebrow">Manual prático · '+e(t['slug'])+'</p><h1>Manual: '+e(t['title'])+'</h1><p>Roteiro de execução e aceite para transformar o diagnóstico em entregáveis verificáveis.</p><a href="/">Voltar ao guia completo</a></div><article><section><h2>Antes de começar</h2><p>'+e(t['problem'])+'</p><p>Delimite o conjunto a trabalhar e nomeie um responsável pelo aceite. Use amostras sem dados pessoais sempre que possível. Preserve uma referência da situação inicial e registre o que será alterado. A execução deve respeitar permissões, contratos e impedimentos aplicáveis ao acervo.</p></section><section><h2>Procedimento por etapa</h2>'+steps(t)+'</section><section><h2>Ficha de controle para adaptar</h2><div class="table-wrap"><table><tr><th>Campo</th><th>Preenchimento esperado</th></tr><tr><td>Escopo e identificador</td><td>Processo, lote ou conjunto incluído e limites do trabalho</td></tr><tr><td>Fonte e requisito</td><td>Documento de referência, versão e decisão de aplicabilidade</td></tr><tr><td>Responsáveis</td><td>Executor, revisor e aprovador com alçadas definidas</td></tr><tr><td>Evidência</td><td>Localização do registro que permite reproduzir a conferência</td></tr><tr><td>Exceção e providência</td><td>Divergência, impacto, responsável, prazo e situação</td></tr><tr><td>Aceite</td><td>Resultado verificado, data e responsável pela aprovação</td></tr></table></div><p><a class="button" href="/modelo-controle.csv" download>Baixar ficha de controle CSV</a></p></section><section><h2>Critérios específicos de verificação</h2>'+controls(t)+'</section><section><h2>Como tratar uma divergência</h2><p>Pause a ação afetada, preserve o registro de entrada e descreva o comportamento observado. Diferencie uma falha pontual de um problema que possa atingir o lote inteiro. Encaminhe a decisão à alçada responsável e registre a providência antes de repetir a operação.</p><p>Depois da correção, repita a conferência que detectou a falha e verifique um caso de controle. Mantenha a evidência do resultado anterior e do resultado corrigido. Pendências aceitas precisam de justificativa e responsável; não as transforme silenciosamente em itens aprovados.</p></section><section><h2>Cenário para treinar a equipe</h2><p>'+e(t['example'])+'</p><p>Peça à equipe para identificar o ponto de controle, a evidência esperada e a pessoa responsável por decidir. O objetivo do exercício é verificar se o procedimento é compreensível e executável com os recursos disponíveis.</p></section><section><h2>Checklist de encerramento</h2><ul><li>Escopo conciliado com os itens efetivamente tratados.</li><li>Controles específicos conferidos e evidências localizáveis.</li><li>Exceções identificadas, com decisões e responsáveis.</li><li>Acesso e integridade verificados conforme o projeto.</li><li>Aceite registrado e orientação entregue à equipe de operação.</li></ul></section>'+editorial(t)+'</article>'
 (d/'manual/index.html').write_text(shell(t,'Manual — '+t['title'],'manual/',manual))
 import csv,io
 s=io.StringIO();w=csv.writer(s);w.writerow(['Controle','Evidência esperada','Responsável sugerido','Responsável designado','Situação','Data','Referência da evidência']);w.writerows([r+['','','',''] for r in t['controls']]);(d/'modelo-controle.csv').write_text('\ufeff'+s.getvalue())
 (d/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+url(t,'sitemap.xml')+'\n')
 (d/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+xml(url(t,p))+'</loc><lastmod>'+DATA['date']+'</lastmod></url>' for p in ['','manual/'])+'</urlset>')
 (d/'llms.txt').write_text('# '+t['title']+'\n\n'+t['answer']+'\n\n- [Guia]('+url(t)+')\n- [Manual]('+url(t,'manual/')+')\n\nAutor institucional: Arquindex. Exemplos didáticos. Consulte as fontes e a data de cada página. Este arquivo não garante uso por sistemas de IA.\n')
 (d/'.htaccess').write_text('Options -Indexes\nAddType text/vtt .vtt\nAddDefaultCharset UTF-8\n')
 return d

def videos(t,d):
 from PIL import Image,ImageDraw,ImageFont
 media=d/'media';media.mkdir(exist_ok=True)
 regular='/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf';bold='/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf'
 scenes=[(t['title'],'Guia técnico Arquindex · 3 etapas')]+[(str(i)+' · '+a,b) for i,(a,b) in enumerate(t['steps'],1)]
 vtt=['WEBVTT','']
 for i,(title,detail) in enumerate(scenes):
  im=Image.new('RGB',(1280,720),'#102d3d');dr=ImageDraw.Draw(im)
  dr.rectangle((60,64,145,71),fill='#d6aa5c');dr.text((60,100),'ARQUINDEX / BIBLIOTECA TÉCNICA',font=ImageFont.truetype(bold,22),fill='#d6aa5c')
  lines=textwrap.wrap(title,37)
  for k,line in enumerate(lines):dr.text((60,180+k*62),line,font=ImageFont.truetype(bold,45),fill='white')
  # Entire detail also exists in captions and transcript; visual frame uses a readable summary.
  summary=detail.split('. ')[0]+('.' if '. ' in detail else '')
  for k,line in enumerate(textwrap.wrap(summary,66)[:4]):dr.text((60,390+k*38),line,font=ImageFont.truetype(regular,27),fill='#d5e0e6')
  dr.text((60,650),host(t)+'  •  '+str(i+1)+'/4',font=ImageFont.truetype(regular,19),fill='#d5e0e6')
  im.save(media/f'frame-{i}.png')
  if i==0:im.save(media/'poster.jpg',quality=88)
  vtt.extend([f'00:00:{i*6:02d}.000 --> 00:00:{(i+1)*6:02d}.000',title+'\n'+summary,''])
 (media/'legendas.vtt').write_text('\n'.join(vtt))
 cmd=['ffmpeg','-hide_banner','-loglevel','error','-y','-framerate','1/6','-i',str(media/'frame-%d.png'),'-t','24','-vf','fps=24','-c:v','libx264','-preset','veryfast','-crf','26','-pix_fmt','yuv420p','-movflags','+faststart',str(media/'guia.mp4')]
 subprocess.run(cmd,check=True)
 for p in media.glob('frame-*.png'):p.unlink()

if __name__=='__main__':
 ap=argparse.ArgumentParser();ap.add_argument('--videos',action='store_true');args=ap.parse_args()
 assert len(TOPICS)==20
 for t in DATA['topics']:
  d=build(t)
  if args.videos:videos(t,d)
 print(json.dumps({'portals':len(TOPICS),'html_pages':len(list(OUT.rglob('*.html'))),'videos':len(list(OUT.rglob('*.mp4')))},ensure_ascii=False))
